{'code': "from qgis.PyQt.QtWidgets import QToolBar, QCheckBox, QLabel, QComboBox, QWidget
mw = iface.mainWindow()
tb = mw.findChild(QToolBar, 'mMeshToolBar')
res = {'visible_widgets': []}
if tb:
    for w in tb.findChildren(QWidget):
        if w.isVisible() and w.metaObject().className() in ('QCheckBox','QLabel','QComboBox','QgsFilterLineEdit','QgsDoubleSpinBox'):
            txt = ''
            for attr in ('text','currentText'):
                if hasattr(w, attr):
                    try:
                        v = getattr(w, attr)()
                        if v:
                            txt = v
                            break
                    except Exception:
                        pass
            res['visible_widgets'].append({'class': w.metaObject().className(), 'text': txt})
result = res"}

